import json
sh=json.load(open('shots_timed.json'))
for win in (120000,180000,240000):
    out=[]; last={}
    for s in sh:
        i=s['id']
        if i in last and s['startMs']-last[i] < win:
            out[-1]['endMs']=s['endMs']  # absorb
        else:
            out.append(dict(s))
        last[i]=s['startMs']
    durs=[(x['endMs']-x['startMs'])/1000 for x in out]
    print("win",win/1000,"shots",len(out),"max",round(max(durs),1),">6s",sum(1 for d in durs if d>6),">8s",sum(1 for d in durs if d>8))
EOF

